const $=id=>document.getElementById(id);let mode='practice',stream=null,anchors=[],running=false,held=false,lift=0,points=0,active=0,rest=0,last=performance.now(),sampleTime=0,smoothed=0,missing=0;
const video=$('video'),canvas=$('processing'),ctx=canvas.getContext('2d',{willReadFrequently:true}),overlay=$('overlay'),oc=overlay.getContext('2d');canvas.width=320;canvas.height=240;overlay.width=320;overlay.height=240;
function say(s){$('message').textContent=s}function stop(){if(stream)stream.getTracks().forEach(t=>t.stop());stream=null;video.srcObject=null;anchors=[];running=false;smoothed=0;$('cameraHint').hidden=false;$('disconnect').hidden=true;$('calibrate').hidden=true;$('connect').hidden=false;$('connect').disabled=false;$('connect').textContent='Turn on camera';$('status').textContent='Allow camera access, then tap each ball at rest: red, yellow, green.';oc.clearRect(0,0,320,240)}
function select(m){held=false;stop();mode=m;if(typeof resetMine==='function')resetMine();lift=0;active=0;points=0;rest=0;$('stars').textContent='☆ 0 / 3';$('practicePanel').hidden=m!=='practice';$('cameraPanel').hidden=m!=='camera';$('practice').classList.toggle('selected',m==='practice');$('camera').classList.toggle('selected',m==='camera');$('modeLabel').textContent=m==='practice'?'● PRACTICE MODE':'◉ CAMERA MODE';say(m==='practice'?'Hi, I’m Pip. Ready to explore?':'Let’s set up with a grown-up.');$('tracking').textContent='Three little balls. One big adventure.'}
