$('float').onpointerdown=e=>{e.preventDefault();$('float').setPointerCapture(e.pointerId);held=true};$('float').onpointerup=$('float').onpointercancel=()=>held=false;window.addEventListener('keydown',e=>{if(e.code==='Space'&&mode==='practice'&&!$('help').open&&!/BUTTON|SELECT/.test(document.activeElement.tagName)){e.preventDefault();held=true}});window.addEventListener('keyup',e=>{if(e.code==='Space')held=false});window.addEventListener('blur',()=>held=false);document.addEventListener('visibilitychange',()=>{held=false;if(document.hidden&&stream){stop();say('Camera stopped. Reconnect when you’re ready.')}});window.addEventListener('pagehide',stop);
async function connect(){stop();$('connect').disabled=true;$('status').textContent='Waiting for camera permission…';try{if(!navigator.mediaDevices?.getUserMedia)throw Error('Camera access needs HTTPS and a supported browser.');stream=await navigator.mediaDevices.getUserMedia({audio:false,video:$('devices').value?{deviceId:{exact:$('devices').value},width:640,height:480}:{facingMode:'environment',width:640,height:480}});video.srcObject=stream;await video.play();$('cameraHint').hidden=true;$('connect').hidden=true;$('disconnect').hidden=false;$('calibrate').hidden=false;const current=stream.getVideoTracks()[0].getSettings().deviceId;const cameras=(await navigator.mediaDevices.enumerateDevices()).filter(d=>d.kind==='videoinput');$('devices').replaceChildren(...cameras.map((d,i)=>{const o=document.createElement('option');o.value=d.deviceId;o.textContent=d.label||`Camera ${i+1}`;o.selected=d.deviceId===current;return o}));resetCalibration()}catch(e){stop();$('status').textContent=e.name==='NotAllowedError'?'Camera permission was denied. Allow it in your browser settings, or use Practice.':e.name==='NotFoundError'?'No camera found. You can still play in Practice.':e.message}}
function resetCalibration(){anchors=[];running=false;smoothed=0;oc.clearRect(0,0,320,240);$('status').textContent='Keep the device still. Tap the RED ball at rest.';say('A grown-up can help with these three taps.')} $('connect').onclick=connect;$('disconnect').onclick=()=>{stop();say('Camera is off. Take your time.');};$('calibrate').onclick=resetCalibration;$('devices').onchange=()=>{if(stream)connect()};
function hsv(r,g,b){r/=255;g/=255;b/=255;const max=Math.max(r,g,b),min=Math.min(r,g,b),d=max-min;let h=0;if(d){if(max===r)h=((g-b)/d)%6;else if(max===g)h=(b-r)/d+2;else h=(r-g)/d+4;h*=60;if(h<0)h+=360}return [h,max?d/max:0,max]}
function hueDist(a,b){return Math.min(Math.abs(a-b),360-Math.abs(a-b))}
overlay.onclick=e=>{if(!stream||anchors.length===3)return;ctx.drawImage(video,0,0,320,240);const box=overlay.getBoundingClientRect(),x=(e.clientX-box.left)/box.width*320,y=(e.clientY-box.top)/box.height*240;const data=ctx.getImageData(Math.max(0,Math.min(313,Math.round(x)-3)),Math.max(0,Math.min(233,Math.round(y)-3)),7,7).data;let sx=0,sy=0,n=0;for(let i=0;i<data.length;i+=4){const [h,s,v]=hsv(data[i],data[i+1],data[i+2]);if(s>.35&&v>.15){sx+=Math.cos(h*Math.PI/180);sy+=Math.sin(h*Math.PI/180);n++}}if(n<10){$('status').textContent='Tap the colored center of the ball, away from glare.';return}const h=(Math.atan2(sy,sx)*180/Math.PI+360)%360,expected=[0,50,135][anchors.length],limit=[30,30,50][anchors.length];if(hueDist(h,expected)>limit){$('status').textContent=`Please tap the ${['red','yellow','green'][anchors.length]} ball. Try better lighting if needed.`;return}anchors.push({x,y,h});if(anchors.length<3)$('status').textContent=`Now tap the ${['RED','YELLOW','GREEN'][anchors.length]} ball at rest.`;else{running=true;$('status').textContent='Tracking ready. Use your prescribed routine; no need to lift every ball.';say('Pip is ready. Follow your usual routine.')}drawMarkers(anchors.map(a=>({...a,found:true})))};
function drawMarkers(list){oc.clearRect(0,0,320,240);list.forEach((a,i)=>{oc.strokeStyle=['#f65353','#f0c43f','#41ad79'][i];oc.lineWidth=2;oc.beginPath();oc.arc(a.x,a.y,10,0,Math.PI*2);oc.stroke();oc.fillStyle='#fff';oc.font='bold 10px sans-serif';oc.fillText(String(i+1),a.x-3,a.y+3)})}
function track(){ctx.drawImage(video,0,0,320,240);const d=ctx.getImageData(0,0,320,240).data;let levels=[],marks=[];for(const a of anchors){let count=0,sumY=0,sumX=0;for(let y=Math.max(0,Math.floor(a.y-155));y<Math.min(240,a.y+15);y+=2)for(let x=Math.max(0,Math.floor(a.x-20));x<Math.min(320,a.x+20);x+=2){const i=(y*320+x)*4,[h,s,v]=hsv(d[i],d[i+1],d[i+2]);if(s>.38&&v>.16&&hueDist(h,a.h)<18){count++;sumY+=y;sumX+=x}}const found=count>12;if(found){const y=sumY/count;levels.push(Math.max(0,Math.min(1,(a.y-y)/100)));marks.push({x:sumX/count,y})}}drawMarkers(marks);if(levels.length!==3){missing++;smoothed=0;$('tracking').textContent='Tracking lost • keep all three balls visible';if(missing>10)say('Let’s check the camera view.');return 0}missing=0;smoothed=smoothed*.65+Math.max(...levels)*.35;$('tracking').textContent='● Tracking 3 balls • on-device vision';return smoothed}
function frame(now){const dt=Math.min((now-last)/1000,.1);last=now;let input=mode==='practice'&&held?1:0;if(mode==='camera'&&running&&video.readyState>=2){if(now-sampleTime>100){track();sampleTime=now}input=smoothed}if($('help').open)input=0;if(typeof game!=='undefined'&&game==='mine'){mineFrame(input,dt,mode==='practice'||(running&&missing===0));requestAnimationFrame(frame);return}if(rest>0){rest-=dt;input=0;if(rest<=0){points=0;active=0;$('stars').textContent='☆ 0 / 3';say('Ready whenever you are.')}}lift+=(input-lift)*Math.min(1,dt*3);$('balloon').style.bottom=`${100+lift*175}px`;if(input>.12&&rest<=0){active+=dt;if(active>1.2){active=0;points++;$('stars').textContent=`★ ${points} / 3`;say(['','A little lift. Lovely!','Hello, clouds!','You found the cloud meadow! Take a break.'][points]);if(points>=3)rest=10}}else active=Math.max(0,active-dt);requestAnimationFrame(frame)}requestAnimationFrame(frame);
